// Package schema is verse's self-description: every tony signature the runtime's own types
// generate, indexed by name and served over HTTP so the API can be read as data rather than
// as prose.
//
// It is an INDEX, not a source. The signatures live with the packages that declare the types
// (api.Schema, trigger.Schema, …), generated by tony-codegen from the Go structs, so they
// cannot drift from the code. This package only gathers and names them.
//
// The one exception is curated.tony, for types codegen cannot describe correctly. Where a
// signature came from is OUR problem, not the reader's: what is published is one flat set of
// signatures, because a caller resolving verse-match wants its shape, and "hand-written or
// derived" tells them nothing they can act on. The distinction still matters internally —
// a curated signature can drift from the code and a generated one cannot — so Curated exists
// for the test that keeps the curated set honest. See curated_test.go.
//
// What is published are I/O SHAPES: what goes on the wire, which is what tony-codegen
// generates from. A tony schema can also carry an `accept:` clause and validate documents;
// none of these do, generated or curated, and that is a separate thing to author deliberately
// rather than a gap in what is here.
package schema

import (
	_ "embed"
	"fmt"
	"sort"
	"sync"

	"github.com/signadot/tony-format/go-tony/ir"

	"github.com/signadot/verse/api"
	"github.com/signadot/verse/codec"
	"github.com/signadot/verse/config"
	"github.com/signadot/verse/entity"
	"github.com/signadot/verse/launch"
	"github.com/signadot/verse/process"
	"github.com/signadot/verse/trigger"
)

//go:embed curated.tony
var curatedDoc []byte

// A signature document is a tony object carrying `define` (the field types) and `signature`
// (its name). The name is how everything else refers to it, so it is the index key.
const (
	sigField  = "signature"
	nameField = "name"
)

var (
	once     sync.Once
	byName   map[string]*ir.Node
	curated  map[string]bool
	loadErr  error
	sortedNm []string
)

// load parses every embedded document once. A malformed embedded schema is a build-time
// mistake surfaced at first use rather than a panic at init: the endpoint reports it, and the
// rest of the server keeps serving.
func load() {
	byName = map[string]*ir.Node{}
	curated = map[string]bool{}

	// Generated first, so a curated entry overrides rather than races it.
	for _, src := range [][]byte{api.Schema, entity.Schema, trigger.Schema, process.Schema, config.Schema, launch.Schema} {
		if err := index(src, false); err != nil {
			loadErr = err
			return
		}
	}
	if err := index(curatedDoc, true); err != nil {
		loadErr = err
		return
	}
	for n := range byName {
		sortedNm = append(sortedNm, n)
	}
	sort.Strings(sortedNm)
}

// index parses a multi-document tony file and files each signature under its name.
func index(src []byte, isCurated bool) error {
	docs, err := codec.ParseNodes(src, codec.Tony)
	if err != nil {
		return fmt.Errorf("parse schema: %w", err)
	}
	for _, d := range docs {
		name := signatureName(d)
		if name == "" {
			continue // a document with no signature name indexes under nothing
		}
		if isCurated {
			// A CURATED SIGNATURE ALWAYS WINS. This used to be "curated fills gaps only" —
			// a generated signature won unless its `define` was empty — on the theory that
			// derived truth beats a hand-written claim and a fixed generator would take over
			// by itself. That rule was wrong, and wrong in the dangerous direction.
			//
			// An empty `define` is the BENIGN symptom of a hand-written codec, and it is
			// what codegen emits for a named map (trigger.Match). For a STRUCT with a custom
			// codec it emits the Go type's shape instead — a non-empty, confident, false
			// description, since `codec=custom` is precisely the declaration that the wire
			// shape is not the Go shape. verse-formula is published as {args, op, req} and
			// emits `!quorum 2`; verse-condition types its `when` as that object and emits an
			// address string. Under the old rule a curated correction for either would have
			// been shadowed by the lie it was written to replace.
			//
			// So: writing a curated entry is the deliberate act, and removing one is too —
			// as already happened for verse-entity and verse-event once v0.0.93 could derive
			// them. Nothing silently reverts to a generated signature; that is the point.
			curated[name] = true
		}
		byName[name] = d
	}
	return nil
}

// signatureName reads `signature.name` from a signature document.
func signatureName(d *ir.Node) string {
	if d == nil || d.Type != ir.ObjectType {
		return ""
	}
	sig := ir.Get(d, sigField)
	if sig == nil || sig.Type != ir.ObjectType {
		return ""
	}
	n := ir.Get(sig, nameField)
	if n == nil || n.Type != ir.StringType {
		return ""
	}
	return n.String
}

// Names lists every signature, sorted.
func Names() ([]string, error) {
	once.Do(load)
	return sortedNm, loadErr
}

// Get returns one signature document by name.
func Get(name string) (*ir.Node, bool, error) {
	once.Do(load)
	if loadErr != nil {
		return nil, false, loadErr
	}
	d, ok := byName[name]
	return d, ok, nil
}

// Curated reports the names whose signature is hand-written rather than generated — the part
// of the index that is a claim about the code rather than a product of it.
//
// This is BUILD HYGIENE, not part of the served schema: it exists so a test can hold the
// curated set equal to the types that actually need one, and catch the entry that outlives its
// reason. Nothing on the wire says which kind a signature is.
func Curated() ([]string, error) {
	once.Do(load)
	if loadErr != nil {
		return nil, loadErr
	}
	out := make([]string, 0, len(curated))
	for n := range curated {
		out = append(out, n)
	}
	sort.Strings(out)
	return out, nil
}

// All returns the whole graph as one document: every signature under its name, and nothing
// else. Curated and generated entries sit side by side, indistinguishable, which is the point —
// a reader gets shapes to resolve, not a report on how verse arrived at them.
//
// synthesized carries signatures the CALLER built, indexed under their own names alongside the
// rest. verse-root is the one: it describes the server's surface rather than a Go type, so it
// is derived from a route table this package cannot see and must not pretend to have.
func All(synthesized ...*ir.Node) (*ir.Node, error) {
	once.Do(load)
	if loadErr != nil {
		return nil, loadErr
	}
	sigs := make(map[string]*ir.Node, len(byName)+len(synthesized))
	for n, d := range byName {
		sigs[n] = d.DeepCopy() // parented into a new document; never hand out the index's node
	}
	for _, d := range synthesized {
		if n := signatureName(d); n != "" {
			sigs[n] = d
		}
	}
	return ir.FromMap(map[string]*ir.Node{
		"signatures": ir.FromMap(sigs),
	}), nil
}
